bool ALMetalWorldGBufferRenderer::setAnisotropy(
    std::uint32_t max_anisotropy,
    std::string* error)
{
    if (!mImpl || !mImpl->device)
    {
        setError(error, "Metal world renderer is unavailable");
        return false;
    }
    if (mImpl->command_batch)
    {
        setError(error,
            "Metal world anisotropy cannot change during a command batch");
        return false;
    }
    if (mImpl->max_anisotropy == max_anisotropy &&
        mImpl->diffuse_sampler && mImpl->probe_sampler &&
        mImpl->ramp_sampler)
    {
        return true;
    }

    if (!createWorldAnisotropicSamplers(
            *mImpl->device, max_anisotropy,
            mImpl->diffuse_sampler, mImpl->probe_sampler,
            mImpl->ramp_sampler, error))
    {
        return false;
    }
    mImpl->max_anisotropy = max_anisotropy;
    // Recreate the optional material sampler with the new filtering settings
    // on its next use. Pending material tables own their previous sampler.
    mImpl->shadow_material_sampler.reset();
    return true;
}

std::uint32_t ALMetalWorldGBufferRenderer::anisotropy() const noexcept
{
    return mImpl ? mImpl->max_anisotropy : 1;
}

bool ALMetalWorldGBufferRenderer::beginCommandBatch(
    const std::string& label,
    std::string* error,
    std::size_t max_pending_command_batches)
{
    if (!mImpl || !mImpl->device)
    {
        setError(error, "Metal world renderer is unavailable");
        return false;
    }
    if (mImpl->command_batch)
    {
        setError(error, "Metal world command batch is already active");
        return false;
    }
    if (!mImpl->makeCommandBatchSlot(
            max_pending_command_batches, error))
    {
        return false;
    }
    mImpl->command_batch = mImpl->device->makeCommandBuffer(label, error);
    mImpl->command_batch_valid = static_cast<bool>(mImpl->command_batch);
    mImpl->command_batch_failure.clear();
    mImpl->command_batch_generates_brdf_lut = false;
    return static_cast<bool>(mImpl->command_batch);
}

bool ALMetalWorldGBufferRenderer::beginMainFrameBatch(
    std::uint64_t group, const std::string& label, std::string* error)
{
    if (!mImpl || !mImpl->device || mImpl->command_batch)
    {
        setError(error, "Metal main frame requires an available renderer and no active batch");
        return false;
    }
    ALMetalFrameAdmission::Ticket ticket = 0;
    try
    {
        const auto phase = !ALMetalDiagnosticTelemetry::enabled() ? 0u
            : label == "Alchemy native world G-buffer and ordered sky" ? 1u
            : label == "Alchemy native world light-map and deferred-light chain" ? 2u
            : label == "Alchemy native world opaque and optical post" ? 3u : 0u;
        // The same sparse memory series exists even if a private comparison
        // arm admits every group without blocking. Missing waits are not zero
        // marginal memory. Boundary2 denotes this ordinary admission attempt.
        if (ALMetalDiagnosticTelemetry::enabled()) mImpl->observeMainAdmissionMemory(0, 2);
        ticket = mImpl->reserveMainFrame(group, error, phase);
        if (!ticket) return false;
        auto command = mImpl->device->makeCommandBuffer(label, error);
        if (!command)
        {
            mImpl->main_admission.cancel(ticket);
            return false;
        }
        mImpl->command_batch = std::move(command);
        if (ALMetalDiagnosticTelemetry::enabled())
        {
            const auto token = mImpl->command_batch->diagnosticToken();
            ALMetalDiagnosticTelemetry::recordSessionMetrics(token.session_id,
                ALMetalDiagnosticTelemetry::currentFrameTag(),
                "main_group_command", {group, ticket, token.command_id, phase,
                    mImpl->main_admission.pendingFrameCount(),
                    mImpl->main_admission.pendingSubmissionCount(),
                    mImpl->main_admission.reservationCount(), mImpl->main_pending_group_limit});
        }
    }
    catch (const std::bad_alloc&)
    {
        if (ticket) mImpl->main_admission.cancel(ticket);
        setError(error, "Could not allocate a Metal main frame reservation or command");
        return false;
    }
    mImpl->main_reservation = ticket;
    mImpl->command_batch_valid = true;
    mImpl->command_batch_failure.clear();
    mImpl->command_batch_generates_brdf_lut = false;
    return true;
}

ALMetalWorldMainFrameStats ALMetalWorldGBufferRenderer::mainFrameStats() const noexcept
{
    if (!mImpl) return {};
    auto stats = mImpl->main_stats;
    stats.pending_groups = mImpl->main_admission.pendingFrameCount();
    stats.pending_commands = mImpl->main_admission.pendingSubmissionCount();
    stats.reservations = mImpl->main_admission.reservationCount();
    return stats;
}

bool ALMetalWorldGBufferRenderer::commitCommandBatch(std::string* error)
{
    if (!mImpl || !mImpl->command_batch)
    {
        setError(error, "Metal world command batch is not active");
        return false;
    }
    auto command = std::move(mImpl->command_batch);
    const bool valid = mImpl->command_batch_valid;
    const std::string failure = mImpl->command_batch_failure;
    const bool generates_brdf_lut =
        mImpl->command_batch_generates_brdf_lut;
    const auto shadow_ticket = mImpl->shadow_reservation;
    const auto main_ticket = mImpl->main_reservation;
    mImpl->command_batch_valid = true;
    mImpl->command_batch_failure.clear();
    mImpl->command_batch_generates_brdf_lut = false;
    if (!valid)
    {
        if (shadow_ticket) mImpl->shadow_submissions->admission.cancel(shadow_ticket);
        mImpl->shadow_reservation = 0;
        mImpl->cancelMainReservation();
        command.reset();
        setError(error, failure.empty()
            ? "Metal world command batch was invalidated"
            : failure);
        auto observers = std::move(mImpl->command_settlement_observers);
        mImpl->command_settlement_observers.clear();
        const auto census = mImpl->settlement_observer_failures;
        notifyCommandSettlement(std::move(observers), census, false);
        return false;
    }
    // Reserve the native retirement entry before committing. A post-commit
    // container allocation must not lose the only submission receipt.
    ALMetalCommandBuffer* queued = nullptr;
    try
    {
        if (shadow_ticket)
        {
            mImpl->shadow_submissions->pending.push_back({shadow_ticket, std::move(command)});
            queued = mImpl->shadow_submissions->pending.back().command.get();
        }
        else
        {
            mImpl->pending_command_batches.push_back({std::move(command), main_ticket});
            queued = mImpl->pending_command_batches.back().command.get();
        }
    }
    catch (const std::bad_alloc&)
    {
        if (shadow_ticket) mImpl->shadow_submissions->admission.cancel(shadow_ticket);
        mImpl->shadow_reservation = 0;
        mImpl->cancelMainReservation();
        setError(error, "Could not reserve Metal command retirement storage");
        auto observers = std::move(mImpl->command_settlement_observers);
        mImpl->command_settlement_observers.clear();
        notifyCommandSettlement(std::move(observers), mImpl->settlement_observer_failures, false);
        return false;
    }
    const bool committed = queued->commit(error);
    if (committed && generates_brdf_lut)
    {
        mImpl->brdf_lut_ready = true;
    }
    if (shadow_ticket)
    {
        if (committed)
        {
            if (!mImpl->shadow_submissions->admission.submitted(shadow_ticket))
                std::fprintf(stderr, "Alchemy Metal committed shadow lost its reservation\n");
        }
        else
        {
            mImpl->shadow_submissions->pending.pop_back();
            mImpl->shadow_submissions->admission.cancel(shadow_ticket);
        }
    }
    else if (!committed) mImpl->pending_command_batches.pop_back();
    if (main_ticket)
    {
        if (committed)
        {
            if (!mImpl->main_admission.submitted(main_ticket))
                std::fprintf(stderr, "Alchemy Metal committed main frame lost its reservation\n");
            ++mImpl->main_stats.committed;
            mImpl->main_reservation = 0;
            mImpl->main_stats.peak_pending_groups = std::max(mImpl->main_stats.peak_pending_groups,
                mImpl->main_admission.pendingFrameCount());
            mImpl->main_stats.peak_pending_commands = std::max(mImpl->main_stats.peak_pending_commands,
                mImpl->main_admission.pendingSubmissionCount());
        }
        else
        {
            ++mImpl->main_stats.failed;
            mImpl->cancelMainReservation();
        }
    }
    mImpl->shadow_reservation = 0;
    auto observers = std::move(mImpl->command_settlement_observers);
    mImpl->command_settlement_observers.clear();
    const auto census = mImpl->settlement_observer_failures;
    // Admission/commit and resource retirement identity are settled first.
    // Observers may begin/register a later transaction without being consumed
    // by this one. Their exceptions cannot change an actual commit result.
    notifyCommandSettlement(std::move(observers), census, committed);
    return committed;
}

void ALMetalWorldGBufferRenderer::cancelCommandBatch()
{
    if (mImpl)
    {
        mImpl->command_batch.reset();
        mImpl->cancelMainReservation();
        if (mImpl->shadow_reservation)
            mImpl->shadow_submissions->admission.cancel(mImpl->shadow_reservation);
        mImpl->shadow_reservation = 0;
        mImpl->command_batch_valid = true;
        mImpl->command_batch_failure.clear();
        mImpl->command_batch_generates_brdf_lut = false;
        auto observers = std::move(mImpl->command_settlement_observers);
        mImpl->command_settlement_observers.clear();
        const auto census = mImpl->settlement_observer_failures;
        notifyCommandSettlement(std::move(observers), census, false);
    }
}

bool ALMetalWorldGBufferRenderer::beginShadowFrameBatch(
    std::uint64_t frame, const std::string& label, std::string* error)
{
    if (!mImpl || !mImpl->device || mImpl->command_batch)
    {
        setError(error, "Metal shadow frame requires an available renderer and no active batch");
        return false;
    }
    const auto ticket = mImpl->reserveShadowFrame(frame, error);
    if (!ticket) return false;
    std::unique_ptr<ALMetalCommandBuffer> command;
    try { command = mImpl->device->makeCommandBuffer(label, error); }
    catch (...)
    {
        mImpl->shadow_submissions->admission.cancel(ticket);
        throw;
    }
    if (!command)
    {
        mImpl->shadow_submissions->admission.cancel(ticket);
        return false;
    }
    mImpl->shadow_reservation = ticket;
    mImpl->command_batch = std::move(command);
    mImpl->command_batch_valid = true;
    mImpl->command_batch_failure.clear();
    mImpl->command_batch_generates_brdf_lut = false;
    return true;
}

bool ALMetalWorldGBufferRenderer::observeCommandBatchSettlement(
    std::function<void(bool)> observer, std::string* error)
{
    if (!mImpl || !mImpl->command_batch || !observer)
    {
        setError(error, "Metal command settlement observer requires an active batch and callback");
        return false;
    }
    mImpl->command_settlement_observers.push_back(std::move(observer));
    return true;
}

bool ALMetalWorldGBufferRenderer::commandBatchActive() const
{
    return mImpl && static_cast<bool>(mImpl->command_batch);
}

bool ALMetalWorldGBufferRenderer::shadowEncodingActive() const noexcept
{ return mImpl && mImpl->shadow_submissions->adopted != 0; }

bool ALMetalWorldGBufferRenderer::commandBatchSlotAvailable(
    std::size_t max_pending) const noexcept
{
    if (!mImpl || !mImpl->device || mImpl->command_batch) return false;
    std::size_t pending = 0;
    for (const auto& command : mImpl->pending_command_batches)
    {
        const auto status = command->status();
        if (status == ALMetalCommandStatus::error) return false;
        if (status != ALMetalCommandStatus::completed) ++pending;
    }
    return pending < std::max<std::size_t>(max_pending, 1);
}

